// Document defines model for Document.
type Document struct {
	AddedAt time.Time `json:"addedAt"`

	// Amount 内置字段“金额”，两位小数，如 326.40
	Amount *string `json:"amount,omitempty"`

	// ArchiveSize 可搜索版的字节数
	ArchiveSize *int64 `json:"archiveSize,omitempty"`

	// Asn 原件编号；没有时省略
	Asn  *int64 `json:"asn,omitempty"`
	Book *Book  `json:"book,omitempty"`

	// Checksum 原件的 SHA-256
	Checksum string `json:"checksum"`

	// Content 识别出的文字；敏感文档在没有确认密码时为空（locked）
	Content string `json:"content"`

	// ContentEditedAt 识别文字最近一次人工修改的时间（v1.3.7）；没有改过或重新识别后省略
	ContentEditedAt *time.Time `json:"contentEditedAt,omitempty"`

	// ConversionPending Office 文档或邮件还没有转成 PDF：入库时没有配置 Gotenberg，配好后每小时自动转换一批（v1.9.1）
	ConversionPending *bool  `json:"conversionPending,omitempty"`
	CorrespondentId   *int64 `json:"correspondentId,omitempty"`

	// CreatedDate 文档日期
	CreatedDate    openapi_types.Date `json:"createdDate"`
	DocumentTypeId *int64             `json:"documentTypeId,omitempty"`

	// DrawerId 所在抽屉；未入抽屉时省略
	DrawerId *int64 `json:"drawerId,omitempty"`

	// DrawerManual 手动放入（或手动设为未入抽屉），收纳规则不会移动它
	DrawerManual bool `json:"drawerManual"`

	// DueDate 内置字段“到期日”
	DueDate *openapi_types.Date `json:"dueDate,omitempty"`

	// FieldSources 各字段的值从哪里来（设计文档 3.3）；没有记录的字段省略
	FieldSources FieldSources `json:"fieldSources"`

	// FieldValues 请求参数 fields 里的自定义字段中有值的那些（v1.5.6）
	FieldValues *[]FieldValue `json:"fieldValues,omitempty"`

	// Fields 有值的自定义字段（含内置字段）
	Fields []FieldValue `json:"fields"`

	// HasArchive 有可搜索版（OCR 生成的 PDF/A）
	HasArchive bool `json:"hasArchive"`

	// HasCover 书籍有单独的封面图（GET /documents/{id}/cover）；没有时省略
	HasCover *bool `json:"hasCover,omitempty"`

	// HasLab 有识别出的检查结果（v1.9.11）；详情页只在这时取 /documents/{id}/lab
	HasLab       *bool `json:"hasLab,omitempty"`
	HasThumbnail bool  `json:"hasThumbnail"`

	// Highlight 有关键词时：命中片段，按顺序拼起来即是片段原文，hit 为命中的词
	Highlight *[]HighlightSegment `json:"highlight,omitempty"`
	Id        int64               `json:"id"`

	// Inbox 在待整理中
	Inbox bool `json:"inbox"`

	// IsBook 是书籍（有书目）
	IsBook bool `json:"isBook"`

	// IsMilestone 标记为大事，出现在年度回顾的大事记里
	IsMilestone bool `json:"isMilestone"`

	// LinkedFrom 文档链接字段指向这份的文档（v1.5.3，最多 100 份，新的在前）
	LinkedFrom *[]LinkedDocument `json:"linkedFrom,omitempty"`

	// LocationId 原件的存放位置（v1.6.3）
	LocationId *int64 `json:"locationId,omitempty"`

	// Locked 敏感文档，还没有确认密码：识别文字、预览和文件都不给（v1.6.4）
	Locked   *bool  `json:"locked,omitempty"`
	MimeType string `json:"mimeType"`

	// ModifiedAt 保存修改时原样传回，用于检查修改冲突
	ModifiedAt time.Time `json:"modifiedAt"`
	NoteCount  int       `json:"noteCount"`

	// OriginalEncrypted 原件是加密的 PDF（预览与搜索使用解密后的可搜索版）
	OriginalEncrypted *bool  `json:"originalEncrypted,omitempty"`
	OriginalFilename  string `json:"originalFilename"`

	// OriginalSize 原件的字节数
	OriginalSize *int64 `json:"originalSize,omitempty"`
	PageCount    int    `json:"pageCount"`

	// PageEdits 页面编辑的状态；页码按编辑之前的 PDF 计
	PageEdits *PageEdits `json:"pageEdits,omitempty"`

	// PersonId 家人（v1.6.3）
	PersonId *int64 `json:"personId,omitempty"`

	// Privacy 我对这份文档隐私的权限（v1.8.0）
	Privacy *DocumentPrivacy `json:"privacy,omitempty"`

	// Private 家人的私密文档（v1.8.0）：只有这位家人本人、照看人、被授权的人和上传者（没被收回时）看得到
	Private *bool `json:"private,omitempty"`

	// Reading 调用者自己的阅读状态与进度（文档列表中）；没有时省略
	Reading *ReadingSummary `json:"reading,omitempty"`

	// RuleDrawerId 手动放入的文档：按当前收纳规则本应放入的抽屉（交还给规则后的去向）；没有则省略
	RuleDrawerId *int64 `json:"ruleDrawerId,omitempty"`

	// Sensitive 敏感文档（v1.6.4）：自己标了，或在敏感抽屉里。列表里没有命中片段；预览、文件和识别文字要先确认密码
	Sensitive *bool `json:"sensitive,omitempty"`

	// SensitiveMarked 文档自己标为敏感（不算抽屉的）
	SensitiveMarked *bool `json:"sensitiveMarked,omitempty"`

	// Source 添加方式：网页上传、API、手机、监听目录、邮件、上传链接（v1.6.2）、从 Paperless 导入、远程收件夹（v1.7.7）
	Source DocumentSource `json:"source"`
	TagIds []int64        `json:"tagIds"`
	Title  string         `json:"title"`
}

// DocumentSource 添加方式：网页上传、API、手机、监听目录、邮件、上传链接（v1.6.2）、从 Paperless 导入、远程收件夹（v1.7.7）
type DocumentSource string

